import {contrast} from './core.mjs';
export function colourHSL(hex){if(typeof hex!=='string'||!/^#[a-f\d]{6}$/i.test(hex))hex='#709f48';const [r,g,b]=(hex.match(/[a-f\d]{2}/gi)||['70','9f','48']).map(v=>parseInt(v,16)/255),hi=Math.max(r,g,b),lo=Math.min(r,g,b),d=hi-lo,l=(hi+lo)/2;let h=0;if(d)h=(hi===r?(g-b)/d+(g<b?6:0):hi===g?(b-r)/d+2:(r-g)/d+4)*60;return {h,s:d?d/(1-Math.abs(2*l-1))*100:0,l:l*100}}
export function colourHex(h,s,l){h=((h%360)+360)%360/360;s=Math.max(0,Math.min(100,s))/100;l=Math.max(0,Math.min(100,l))/100;const a=s*Math.min(l,1-l),channel=n=>{const k=(n+h*12)%12;return Math.round(255*(l-a*Math.max(-1,Math.min(k-3,9-k,1)))).toString(16).padStart(2,'0')};return '#'+channel(0)+channel(8)+channel(4)}
export const harmonies={complementary:[0,180],analogous:[-30,0,30],split:[0,150,210],triadic:[0,120,240],tetradic:[0,90,180,270],monochrome:[0,0,0,0]};
export function harmonyColours(hex,kind='complementary'){const {h,s,l}=colourHSL(hex);return (Object.hasOwn(harmonies,kind)?harmonies[kind]:harmonies.complementary).map((offset,i)=>colourHex(h+offset,s,kind==='monochrome'?[20,40,60,80][i]:l))}
export function contrastResult(fg,bg){const ratio=contrast(fg,bg);return {ratio,normalAA:ratio>=4.5,largeAA:ratio>=3,normalAAA:ratio>=7}}
export function colourWheel(hex,kind){const {h,s,l}=colourHSL(hex);let body='';for(let i=0;i<120;i++){const a=i/120*Math.PI*2-Math.PI/2,b=(i+1.2)/120*Math.PI*2-Math.PI/2;body+=`<path d="M${160+125*Math.cos(a)} ${160+125*Math.sin(a)}A125 125 0 0 1 ${160+125*Math.cos(b)} ${160+125*Math.sin(b)}" stroke="${colourHex(i*3,80,55)}" stroke-width="40" fill="none"/>`}for(const c of harmonyColours(hex,kind)){const hue=colourHSL(c).h/180*Math.PI-Math.PI/2;body+=`<circle cx="${160+125*Math.cos(hue)}" cy="${160+125*Math.sin(hue)}" r="10" fill="${c}" stroke="white" stroke-width="3"/>`}return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 320" role="img" aria-label="Colour harmony wheel, base hue ${Math.round(h)} degrees"><circle cx="160" cy="160" r="65" fill="${colourHex(h,s,l)}"/>${body}</svg>`}
